<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {request} from './client'
import {capabilities,refreshCapabilities} from './capabilities'
import {hostedCheckout} from './contracts'
import {receiptHtml,downloadHtml} from './receipt'
const props=defineProps({controlPlane:Boolean}),data=ref(null),organizations=ref([]),tenant=ref(''),error=ref(''),busy=ref(false),quote=ref(null),attempt=ref(null),receipt=ref(null),note=ref('')
let timer
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function rpc(action,args={}){if(!props.controlPlane)return request('billing_bridge','request',{action,args});if(action==='summary')return request('premium','summary',{tenant:tenant.value});if(action==='quote')return request('subscription_payments','quote',{tenant:tenant.value,plan:'PREMIUM AI'});if(action==='request_pricing')return request('premium','request_pricing',{tenant:tenant.value});return request(action==='receipt'?'premium':'subscription_payments',action,args)}
async function load(){await run(async()=>{if(props.controlPlane){const r=await request('release','billing',{},'GET');organizations.value=r.organizations;if(!tenant.value)tenant.value=r.organizations[0]?.name||'';if(tenant.value)data.value=await rpc('summary')}else{await refreshCapabilities();if(capabilities.value?.role==='Admin')data.value=await rpc('summary');else data.value={subscription:capabilities.value}}})}
async function getQuote(){await run(async()=>quote.value=await rpc('quote'))}
async function checkout(){await run(async()=>{const r=await rpc('checkout',{quote:quote.value.quote});if(r.preview){note.value=r.message;await load();return}sessionStorage.setItem('sisu-premium-attempt',r.attempt);location.assign(hostedCheckout(r.redirect_url))})}
async function poll(){const id=sessionStorage.getItem('sisu-premium-attempt');if(!id)return;await run(async()=>{attempt.value=await rpc('status',{attempt:id});await load()});if(['succeeded','failed','cancelled'].includes(attempt.value?.status)){sessionStorage.removeItem('sisu-premium-attempt');return}timer=setTimeout(poll,15000)}
function printReceipt(){window.print()}
function focus(){load()}
onMounted(async()=>{window.addEventListener('focus',focus);await load();if(props.controlPlane||capabilities.value?.role==='Admin')poll()});onBeforeUnmount(()=>{clearTimeout(timer);window.removeEventListener('focus',focus)})
</script>
<template><section class="release"><h1>{{controlPlane||capabilities?.role==='Admin'?'Subscription':'Institute Plan'}}</h1><p v-if="busy" role="status">Loading…</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="note" role="status">{{note}}</p><button class="button subtle" @click="load" :disabled="busy">Refresh status</button><label v-if="controlPlane">Organization<select v-model="tenant" @change="load"><option v-for="o in organizations" :value="o.name">{{o.title}}</option></select></label>
<template v-if="data"><article class="panel"><h2>{{data.organization||capabilities?.organization}}</h2><p>{{data.subscription.plan}} · {{data.subscription.state}}</p><p v-if="data.subscription.premium_state==='expired'">Premium has expired. Free Starter services remain available while your organization is enabled.</p><p v-if="attempt">Payment: {{attempt.status}}. A checkout return alone does not activate access.</p><p v-if="data.policy_delivery">Institute access update: {{data.policy_delivery.status}}</p></article>
<template v-if="controlPlane||capabilities?.role==='Admin'"><div class="plans"><article class="panel"><h2>Starter</h2><strong>Free</strong><p>Classes, materials, assessments, schedules and notifications.</p><span class="badge">{{data.subscription.plan==='STARTER'?'Current Plan':'Included base services'}}</span></article><article class="panel"><h2>Premium AI</h2><template v-if="data.offer?.available"><strong>{{data.offer.currency}} {{(data.offer.amount_minor/100).toFixed(2)}} / month</strong><p>Role-specific AI, source-grounded study tools and teaching drafts.</p><span v-if="data.subscription.premium_active" class="badge">Current Plan · Active</span><button class="button primary" @click="getQuote" :disabled="busy">{{data.subscription.premium_active?'Renew Premium AI':'Upgrade to Premium AI'}}</button></template><template v-else><p>Premium AI pricing has not yet been configured for your institute.</p><button class="button subtle" @click="run(async()=>{await rpc('request_pricing');note='Pricing request recorded for the Platform Owner.'})">Request Premium Pricing</button></template></article></div>
<article v-if="quote" class="panel"><h2>Confirm monthly quote</h2><p>{{quote.currency}} {{(quote.total_minor/100).toFixed(2)}} · Expires {{quote.expires_at}}</p><button class="button primary" @click="checkout" :disabled="busy">Confirm and open secure checkout</button></article>
<article class="panel"><h2>Billing history</h2><p>Premium ends / renews: {{data.subscription.ends_at||'No paid period'}}</p><p v-if="!data.payments?.length">No payment attempts.</p><p v-for="p in data.payments">{{p.status}} · {{p.currency}} {{(p.amount_minor/100).toFixed(2)}} · {{p.creation}}</p><h3>Payment receipts</h3><button v-for="r in data.receipts" class="button subtle" @click="run(async()=>receipt=await rpc('receipt',{name:r.name}))">{{r.name}} · {{r.paid_at}}</button><p v-if="!data.receipts?.length">No verified payment receipts.</p></article>
<article v-if="receipt" class="panel receipt"><h2>Payment receipt {{receipt.name}}</h2><p>{{receipt.plan}} · {{receipt.currency}} {{(receipt.amount_minor/100).toFixed(2)}}</p><p>Period: {{receipt.period_start}} — {{receipt.period_end}}</p><p>Paid: {{receipt.paid_at}}</p><p>Reference: {{receipt.transaction_reference}}</p><button class="button subtle" @click="printReceipt">Print / Save as PDF</button><button class="button subtle" @click="downloadHtml(receiptHtml(receipt),'sisu-payment-receipt.html')">Download printable receipt</button><p>Payment receipt, not a tax invoice.</p></article></template>
<article v-else class="panel"><h2>Your institute services</h2><ul><li v-for="f in capabilities?.features">{{f}}</li></ul><p>Your institute manages its subscription. Your own AI usage is in Account → AI Usage.</p></article></template></section></template>
<style scoped>.plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:18px;margin-top:20px}.plans .button{display:block;margin-top:18px}@media print{.release>*:not(.receipt){display:none}.receipt button{display:none}}</style>
